import { Amplify } from 'aws-amplify';

/**
 * Universal environment variable accessor (Vite client + Node.js SSG)
 */
const env = (typeof import.meta !== 'undefined' && import.meta.env)
  ? import.meta.env
  : (typeof process !== 'undefined' && process.env ? process.env : {});

// Optional dynamic import of amplify_outputs.json (auto-generated by Amplify Gen 2 on deployment)
let outputs = null;
try {
  const outputsModules = (typeof import.meta !== 'undefined' && import.meta.glob)
    ? import.meta.glob('/amplify_outputs.json', { eager: true })
    : {};
  outputs = outputsModules['/amplify_outputs.json']?.default || null;
} catch {
  outputs = null;
}

export const awsConfig = {
  region: outputs?.storage?.aws_region || env.VITE_AWS_REGION || env.AWS_REGION || 'us-east-1',
  storageBucket: outputs?.storage?.bucket_name || env.VITE_AWS_STORAGE_BUCKET_NAME || env.S3_BUCKET_NAME || '',
  cloudFrontUrl: env.VITE_AWS_CLOUDFRONT_URL || '',
  storageBaseUrl: env.VITE_STORAGE_BASE_URL || '',
  identityPoolId: outputs?.auth?.identity_pool_id || env.VITE_AWS_IDENTITY_POOL_ID || '',
  userPoolId: outputs?.auth?.user_pool_id || env.VITE_AWS_USER_POOLS_ID || '',
  userPoolClientId: outputs?.auth?.user_pool_client_id || env.VITE_AWS_USER_POOLS_WEB_CLIENT_ID || '',
};

let isAmplifyConfigured = false;

export function configureAmplify() {
  if (isAmplifyConfigured) return;

  if (outputs) {
    try {
      Amplify.configure(outputs);
      isAmplifyConfigured = true;
      return;
    } catch (err) {
      if (typeof console !== 'undefined' && console.warn) {
        console.warn('[Amplify Storage] Auto-configure with outputs failed, using fallback:', err?.message || err);
      }
    }
  }

  // Fallback to manual configuration via environment variables
  if (awsConfig.storageBucket) {
    try {
      Amplify.configure({
        Storage: {
          S3: {
            bucket: awsConfig.storageBucket,
            region: awsConfig.region,
          },
        },
        Auth: {
          Cognito: {
            identityPoolId: awsConfig.identityPoolId || undefined,
            userPoolId: awsConfig.userPoolId || undefined,
            userPoolClientId: awsConfig.userPoolClientId || undefined,
          },
        },
      });
      isAmplifyConfigured = true;
    } catch (err) {
      if (typeof console !== 'undefined' && console.warn) {
        console.warn('[Amplify Storage] Client config note:', err?.message || err);
      }
    }
  }
}

// Auto-run if configuration is available
configureAmplify();

export default configureAmplify;
